package com.opentv.app.ui;
import android.content.*;import android.os.*;import android.view.View;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.*;import com.opentv.app.R;import com.opentv.app.data.*;import com.opentv.app.model.Channel;import java.util.*;import java.util.concurrent.*;
public class MainActivity extends AppCompatActivity{static final String ALL="https://iptv-org.github.io/iptv/index.category.m3u",CA="https://iptv-org.github.io/iptv/countries/ca.m3u",AB="https://iptv-org.github.io/iptv/subdivisions/ca-ab.m3u",NEWS="https://iptv-org.github.io/iptv/categories/news.m3u",SPORTS="https://iptv-org.github.io/iptv/categories/sports.m3u",MOVIES="https://iptv-org.github.io/iptv/categories/movies.m3u",MUSIC="https://iptv-org.github.io/iptv/categories/music.m3u",KIDS="https://iptv-org.github.io/iptv/categories/kids.m3u";final ExecutorService ex=Executors.newSingleThreadExecutor();final Handler main=new Handler(Looper.getMainLooper());final List<Channel>all=new ArrayList<>();FavoritesStore fav;ChannelAdapter adapter;TextView title,count,empty;ProgressBar progress;String currentUrl=ALL,currentLabel="All Channels";
protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);fav=new FavoritesStore(this);title=findViewById(R.id.sourceTitle);count=findViewById(R.id.channelCount);empty=findViewById(R.id.emptyText);progress=findViewById(R.id.progress);RecyclerView nav=findViewById(R.id.navList);nav.setLayoutManager(new LinearLayoutManager(this));nav.setAdapter(new NavAdapter(Arrays.asList(new NavAdapter.Item("All Channels",ALL),new NavAdapter.Item("Canada",CA),new NavAdapter.Item("Alberta",AB),new NavAdapter.Item("News",NEWS),new NavAdapter.Item("Sports",SPORTS),new NavAdapter.Item("Movies",MOVIES),new NavAdapter.Item("Music",MUSIC),new NavAdapter.Item("Kids",KIDS),new NavAdapter.Item("Favorites",null,true,false)),i->{if(i.favorites)showFavorites();else load(i.label,i.url);}));RecyclerView grid=findViewById(R.id.channelGrid);grid.setLayoutManager(new GridLayoutManager(this,5));adapter=new ChannelAdapter(fav,new ChannelAdapter.Listener(){public void onPlay(Channel c){play(c);}public void onFavoriteChanged(Channel c,boolean n){Toast.makeText(MainActivity.this,n?"Added to favorites":"Removed from favorites",Toast.LENGTH_SHORT).show();}});grid.setAdapter(adapter);RecyclerView cats=findViewById(R.id.categoryList);cats.setLayoutManager(new LinearLayoutManager(this,LinearLayoutManager.HORIZONTAL,false));cats.setAdapter(new CategoryAdapter(c->{}));findViewById(R.id.retryButton).setOnClickListener(v->load(currentLabel,currentUrl));load(currentLabel,currentUrl);}
void load(String label,String url){currentLabel=label;currentUrl=url;title.setText(label);progress.setVisibility(View.VISIBLE);ex.execute(()->{try{List<Channel>x=new PlaylistRepository(this).load(url,false);main.post(()->{all.clear();all.addAll(x);adapter.setItems(all);count.setText(all.size()+" channels");progress.setVisibility(View.GONE);findViewById(R.id.emptyState).setVisibility(all.isEmpty()?View.VISIBLE:View.GONE);});}catch(Exception e){main.post(()->{progress.setVisibility(View.GONE);findViewById(R.id.emptyState).setVisibility(View.VISIBLE);empty.setText("Could not load playlist\n"+e.getMessage());});}});}
void showFavorites(){currentLabel="Favorites";title.setText(currentLabel);all.clear();all.addAll(fav.all());adapter.setItems(all);count.setText(all.size()+" channels");}
void play(Channel c){Intent i=new Intent(this,PlayerActivity.class);i.putExtra("name",c.name);i.putExtra("url",c.url);i.putExtra("logo",c.logo);i.putExtra("group",c.group);i.putExtra("country",c.country);i.putExtra("language",c.language);i.putExtra("playlist_url",currentUrl);i.putExtra("source_label",currentLabel);startActivity(i);}protected void onDestroy(){ex.shutdownNow();super.onDestroy();}}
